#!/usr/bin/env bash
# Quality guard for the drafter change (force_check's "decode path" rule): continuations generated by stock (twice: the
# noise) and by the candidate, all scored teacher-forced by the STOCK engine, then checked. Run with no other engine up.
set -u
cd /d/Projects/local_ai/strata-lab/runs/fc || exit 1
FC="python /c/src/Strata/tools/force_check.py"
G="--corpus corpus.jsonl --per-kind 4 --offset 0 --new 300"
[ -f setA.json ] || $FC gen cfg-stock.json setA.json $G || exit 1
[ -f setB.json ] || $FC gen cfg-stock.json setB.json $G || exit 1
$FC gen cfg-df2c65.json setC-df2c65.json $G || exit 1
[ -f stockA.tsv ] || $FC score cfg-stock.json setA.json stockA.tsv || exit 1
[ -f stockB.tsv ] || $FC score cfg-stock.json setB.json stockB.tsv || exit 1
$FC score cfg-stock.json setC-df2c65.json cand-df2c65.tsv || exit 1
$FC check --stock stockA.tsv stockB.tsv --cand cand-df2c65.tsv --json check-df2c65.json
echo "check exit $? (0 pass, 1 reject, 2 inconclusive)"
